// ═══════════════════════════════════════════════════════════════
// Normalize Client Dossier — les 3 sources (Upmeet, Audio, PDF) produisent
// déjà le même schéma JSON. Ce noeud nettoie le texte renvoyé par Gemini
// (retire les éventuelles balises Markdown), parse en JSON, comble les
// champs manquants avec des valeurs par défaut sûres, et étiquette la
// source pour traçabilité.
// ═══════════════════════════════════════════════════════════════

function extraireTexteBrut(input) {
  if (input && typeof input === 'object' && !Array.isArray(input)) {
    if (input.content?.parts?.[0]?.text) return input.content.parts[0].text;
    if (input.choices?.[0]?.message?.content) return input.choices[0].message.content;
    if (Array.isArray(input.content) && input.content[0]?.text) return input.content[0].text;
    return JSON.stringify(input);
  }
  if (typeof input === 'string') return input;
  return String(input);
}

const stripFences = (t) => t.trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
const reparer = (t) => t.replace(/,\s*([\]}])/g, '$1').replace(/[\u201C\u201D]/g, '"').replace(/[\u2018\u2019]/g, "'");

function parseSur(texte) {
  try { return JSON.parse(texte); }
  catch (e) { try { return JSON.parse(reparer(texte)); } catch (e2) { throw new Error('Échec parsing JSON : ' + e2.message); } }
}

function defaut(o, chemin, valeur) {
  const parts = chemin.split('.');
  let cur = o;
  for (const p of parts) { cur = cur?.[p]; if (cur === undefined) return valeur; }
  return cur ?? valeur;
}

const results = [];
for (const item of $input.all()) {
  const brut = item.json.output ?? item.json;
  try {
    const d = parseSur(stripFences(extraireTexteBrut(brut)));
    results.push({
      json: {
        identification: d.identification ?? {},
        contexte: d.contexte ?? '',
        besoins: d.besoins ?? {},
        enjeu: d.enjeu ?? {},
        budget: d.budget ?? {},
        echeance: d.echeance ?? {},
        decideurs: d.decideurs ?? {},
        competiteurs: d.competiteurs ?? {},
        verbatims_cles: d.verbatims_cles ?? [],
        engagements_pris_par_l_expert: d.engagements_pris_par_l_expert ?? [],
        pistes_evoquees_sans_engagement: d.pistes_evoquees_sans_engagement ?? [],
        prochaines_etapes: d.prochaines_etapes ?? [],
        sections_non_abordees: d.sections_non_abordees ?? [],
        zones_d_incertitude: d.zones_d_incertitude ?? [],
        anomalies: d.anomalies ?? [],
        source: $node.name.includes('Upmeet') ? 'upmeet' : ($node.name.includes('Audio') ? 'audio' : 'pdf')
      }
    });
  } catch (error) {
    results.push({ json: { error: true, message: error.message, raw: brut } });
  }
}
return results;

