// Flatten Validated Consultants — croise proposition et controle, un item par profil.
function extraire(o) { return o?.output ?? o ?? null; }
let validation = null, proposition = null;
try { proposition = extraire($('Proposal Drafting Agent').first().json); } catch (e) {}
try { validation = extraire($('Validate Proposal Agent').first().json); } catch (e) {}
for (const item of $input.all()) {
  const o = extraire(item.json);
  if (!o) continue;
  if (!validation && Array.isArray(o.controles_par_profil)) validation = o;
  if (!proposition && Array.isArray(o.propositions)) proposition = o;
}
if (!validation || !proposition) {
  return [{ json: { erreur: true, message: "Execute le workflow complet depuis le trigger." } }];
}
const clef = s => String(s ?? '').trim().toLowerCase();
const parProfil = {};
for (const p of proposition.propositions ?? []) if (p.profil) parProfil[clef(p.profil)] = p;

const synth = validation.synthese_client ?? {};
const besoins = synth.besoins_client ?? [];
const solutions = synth.solutions_proposees ?? [];
const PUCE = '• ';
const nb = Math.max(besoins.length, solutions.length);
const enPuces = arr => Array.from({ length: nb }, (_, i) => PUCE + String(arr[i] ?? 'Non précisé')).join('\n');

const results = [];
for (const c of validation.controles_par_profil ?? []) {
  const p = parProfil[clef(c.profil)] ?? {};
  const points = c.points ?? [];
  const bloquants = points.filter(x => x.statut === 'bloquant');
  const chiffrage = p.chiffrage ?? [];
  const dureesChiffrees = chiffrage.filter(b => b.chiffrage_complet === 'oui').map(b => b.duree);
  results.push({
    json: {
      client: proposition.client ?? '', ville: proposition.ville ?? '', consultant_optinovai: proposition.consultant_optinovai ?? '',
      duree_engagement_envisagee: proposition.duree_engagement_envisagee ?? '',
      profil: c.profil, positionnement: (p.positionnement ?? '').toLowerCase().trim() || 'unique',
      expertise_principale: p.expertise_principale ?? '', competences: p.competences ?? '', disponibilite: p.disponibilite ?? '',
      image: p.image ?? '', point_fort: p.point_fort ?? '',
      pictos: Array.isArray(p.pictos) ? p.pictos : [], image_infos: Array.isArray(p.image_infos) ? p.image_infos : [],
      argumentaire: p.argumentaire ?? '', atouts: Array.isArray(p.atouts) ? p.atouts : [],
      ATOUTS: (Array.isArray(p.atouts) ? p.atouts : []).map(a => '– ' + a).join('\n'),
      options_ponctuelles: Array.isArray(p.options_ponctuelles) ? p.options_ponctuelles : [],
      options_non_cataloguees: Array.isArray(p.options_non_cataloguees) ? p.options_non_cataloguees : [],
      reserves: p.reserves ?? '', chiffrage,
      verdict_machine: c.verdict_machine ?? '', est_conforme: c.verdict_machine === 'conforme',
      exploitable: c.verdict_machine === 'conforme' && dureesChiffrees.length > 0, durees_chiffrees: dureesChiffrees,
      detail_controles: points, motifs_bloquants: bloquants.map(x => x.critere + ' : ' + x.commentaire),
      est_remplacement: false, revalide: true,
      BESOINS_CLIENT: enPuces(besoins), SOLUTIONS_PROPOSEES: enPuces(solutions)
    }
  });
}
if (results.length === 0) {
  results.push({ json: { client: proposition.client ?? '', profil: '', verdict_machine: 'pas conforme', est_conforme: false, aucun_profil_controle: true } });
}
return results;

