// Flatten Replacement Consultants
let besoins = '', solutions = '';
try { const f = $('Flatten Consultant Data').first().json; besoins = f.BESOINS_CLIENT ?? ''; solutions = f.SOLUTIONS_PROPOSEES ?? ''; } catch (e) {}
const out = [];
for (const item of $input.all()) {
  const o = item.json.output ?? item.json;
  for (const p of (o.propositions ?? [])) {
    const chiffrage = p.chiffrage ?? [];
    const dureesChiffrees = chiffrage.filter(b => b.chiffrage_complet === 'oui').map(b => b.duree);
    out.push({ json: {
      client: o.client ?? '', ville: o.ville ?? '', consultant_optinovai: o.consultant_optinovai ?? '',
      duree_engagement_envisagee: o.duree_engagement_envisagee ?? '',
      profil: p.profil ?? '', positionnement: p.positionnement_origine || 'remplacement',
      expertise_principale: p.expertise_principale ?? '', competences: p.competences ?? '', disponibilite: p.disponibilite ?? '',
      image: p.image ?? '', point_fort: p.point_fort ?? '', pictos: Array.isArray(p.pictos) ? p.pictos : [], image_infos: Array.isArray(p.image_infos) ? p.image_infos : [],
      argumentaire: p.argumentaire ?? '', atouts: Array.isArray(p.atouts) ? p.atouts : [],
      ATOUTS: (Array.isArray(p.atouts) ? p.atouts : []).map(a => '– ' + a).join('\n'),
      reserves: p.reserves ?? '', chiffrage, durees_chiffrees: dureesChiffrees, exploitable: dureesChiffrees.length > 0,
      profil_remplace: p.profil_remplace ?? '', motifs_bloquants_leves: p.motifs_bloquants_leves ?? [], motifs_bloquants_non_leves: p.motifs_bloquants_non_leves ?? [],
      verdict_machine: 'remplacement non revalide', est_conforme: false, est_remplacement: true, revalide: false,
      BESOINS_CLIENT: besoins, SOLUTIONS_PROPOSEES: solutions
    } });
  }
}
return out;

// Backfill Catalog Fields — recopie deterministe (sans LLM) des colonnes du catalogue
// pour le profil courant de la boucle, en secours des oublis frequents des agents IA.
const offre = $('Merge Validation and Replacement').item.json;
const lignes = $input.all().map(i => i.json);
const normaliser = s => String(s ?? '').trim().toLowerCase();
const chaine = v => (v === null || v === undefined) ? '' : String(v);
const ligne = lignes.find(l => normaliser(l['Profil']) === normaliser(offre.profil));
if (!ligne) {
  return [{ json: { ...offre, catalogue_non_trouve: true }, pairedItem: 0 }];
}
return [{ json: {
  ...offre,
  seniorite: chaine(ligne['Séniorité'] ?? offre.seniorite ?? ''),
  expertise_principale: chaine(ligne['Expertise principale'] ?? offre.expertise_principale ?? ''),
  competences: chaine(ligne['Compétences/Stack'] ?? offre.competences ?? ''),
  disponibilite: chaine(ligne['Disponibilité'] ?? offre.disponibilite ?? ''),
  point_fort: chaine(ligne['Point fort'] ?? ''),
  image: chaine(ligne['Photo'] ?? offre.image ?? ''),
  pictos: [chaine(ligne['Picto 1'] ?? ''), chaine(ligne['Picto 2'] ?? ''), chaine(ligne['Picto 3'] ?? ''), chaine(ligne['Picto 4'] ?? '')],
  image_infos: [chaine(ligne['Image info 1'] ?? ''), chaine(ligne['Image info 2'] ?? ''), chaine(ligne['Image info 3'] ?? '')],
  catalogue_non_trouve: false
}, pairedItem: 0 }];

// Calcul des totaux — TJM régie x jours/mois OU prix forfait, + options.
function toNombre(v) {
  if (v === null || v === undefined) return NaN;
  let s = String(v).trim().replace(/[^0-9,.\-]/g, '').replace(',', '.');
  return (s === '' || s === '-' || s === '.') ? NaN : Number(s);
}
const offre = $('Fill Missing Catalog Data').item.json;
const chiffrage = offre.chiffrage ?? [];
const c = chiffrage.find(x => x.chiffrage_complet === 'oui' && Number.isFinite(toNombre(x.tjm_ht))) ?? chiffrage.find(x => Number.isFinite(toNombre(x.tjm_ht))) ?? chiffrage[0] ?? {};
const tjm = toNombre(c.tjm_ht);
const jours = toNombre(offre.jours_mois_facturation ?? 20); // 20 j/mois par defaut si non precise
const montantTjmMois = Number.isFinite(tjm) ? Math.round(tjm * jours * 100) / 100 : '';
const montantsOptions = (c.options ?? []).map(o => toNombre(o.montant_mensuel_ht));
const totalOptions = montantsOptions.length && montantsOptions.every(Number.isFinite) ? Math.round(montantsOptions.reduce((s, n) => s + n, 0) * 100) / 100 : (montantsOptions.length === 0 ? 0 : '');
const postes = [montantTjmMois, totalOptions].filter(v => typeof v === 'number' && Number.isFinite(v));
const mensualiteEstimee = postes.length ? Math.round(postes.reduce((s, n) => s + n, 0) * 100) / 100 : '';
return { json: {
  ...offre,
  presentationId: $('Duplicate Drive File').item.json.id,
  tjm_ht: tjm === '' || !Number.isFinite(tjm) ? '' : String(tjm),
  montant_tjm_mois: montantTjmMois === '' ? '' : String(montantTjmMois),
  total_options: totalOptions === '' ? '' : String(totalOptions),
  mensualite_estimee: mensualiteEstimee === '' ? '' : String(mensualiteEstimee),
  duree_retenue: String(c.duree || '').replace(/\s*mois\s*/i, '').trim()
} };

// Build Image Requests — insère la photo du consultant et ses pictos de compétences.
const offre = $('Calculate Slide Totals').item.json;
const requests = [];
function insererOuVider(marqueur, url) {
  const u = String(url ?? '').trim();
  if (/^https?:\/\//i.test(u)) {
    requests.push({ replaceAllShapesWithImage: { imageUrl: u, imageReplaceMethod: 'CENTER_INSIDE', containsText: { text: marqueur, matchCase: true } } });
  } else {
    requests.push({ replaceAllText: { containsText: { text: marqueur, matchCase: true }, replaceText: '' } });
  }
}
insererOuVider('{{PHOTO}}', offre.image);
const pictos = Array.isArray(offre.pictos) ? offre.pictos : [];
for (let i = 0; i < 4; i++) insererOuVider('{{PICTO' + (i + 1) + '}}', pictos[i]);
return { json: { presentationId: offre.presentationId, requests, nb_requetes: requests.length } };
